waves.point_eqs_eel:
//Define 3D Shape

//Zylot's dumb 3d wave
fvar = sample*512;
svar = fvar/16;
tvar = 0&svar;
newsample = tvar/3.2;
x1 = sin(newsample*3.1415926*2);
y1 = cos(newsample*3.1415926*2);
z1 = 0;

//modulate values to adjust for rotation on multiple axes, convert to world co-ordinates
y2 = y1*cos(t1)-z1*sin(t1);
z2 = y1*sin(t1)+z1*cos(t1);
x2 = z2*sin(t2)+x1*cos(t2);
z3 = z2*cos(t2)-x1*sin(t2);
x3 = x2*cos(t3)-y2*sin(t3);
y3 = y2*cos(t3)+x2*sin(t3);
//move resulting shape in 3d space
x4 = x3;
y4 = y3;
z4 = z3+5;
//draw 3d shape in 2d
x=0.5+0.5*(x4/(1+z4*0.5));
y=0.5+0.5*(y4/(1+z4*0.5));

r = -.5 + sin(sample*5+((time*5)+9));
r = if(below(r,0),0,r);
g = -.5 + sin(sample*5+time*5);
g = if(below(g,0),0,g);
b = -.5 + sin(sample*5+((time*5)+18));
b = if(below(b,0),0,b);
r = if(above(bass,1.5),1,r);
g = if(above(bass,1.5),1,g);
b = if(above(bass,1.5),1,b);

